const staticData = $getWorkflowStaticData('global');
if (!staticData.memoryBySender) {
  staticData.memoryBySender = {};
}

const inputItems = $input.all();
const out = [];
for (const item of inputItems) {
  const json = item.json;
  const sender = json.sender_phone;
  const memoryWindow = Number(json.cfg_memory_window_turns || 20);
  const incomingText = json.incoming_text || '[empty]';

  const history = staticData.memoryBySender[sender] || [];
  history.push({ role: 'user', text: incomingText, ts: new Date().toISOString() });

  const boundedHistory = history.slice(-memoryWindow);

  // Keep the current behavior stable while we integrate model calls iteratively.
  const assistantText = `You said: ${incomingText}`;

  boundedHistory.push({ role: 'assistant', text: assistantText, ts: new Date().toISOString() });
  staticData.memoryBySender[sender] = boundedHistory.slice(-memoryWindow);

  const rate = Number(json.cfg_estimated_cost_per_1k_chars_usd || 0);
  const totalChars = incomingText.length + assistantText.length;
  const estimatedCostUsd = Number(((totalChars / 1000) * rate).toFixed(6));

  out.push({
    json: {
      ...json,
      assistant_text: assistantText,
      estimated_cost_usd: estimatedCostUsd
    }
  });
}

return out;

const staticData = $getWorkflowStaticData('global');
if (!staticData.monthlyCost) {
  staticData.monthlyCost = {};
}

const now = new Date();
const monthKey = `${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, '0')}`;
const inputItems = $input.all();
const out = [];

for (const item of inputItems) {
  const json = item.json;
  const record = staticData.monthlyCost[monthKey] || { total_usd: 0, alert_sent: false, updated_at: null };
  const delta = Number(json.estimated_cost_usd || 0);

  record.total_usd = Number((record.total_usd + delta).toFixed(6));
  record.updated_at = now.toISOString();
  staticData.monthlyCost[monthKey] = record;

  const threshold = Number(json.cfg_monthly_cost_limit_usd || 25);
  const alertNeeded = Boolean(json.cfg_cost_alert_enabled) && !record.alert_sent && record.total_usd >= threshold;

  out.push({
    json: {
      ...json,
      cost_month_key: monthKey,
      cost_total_usd: record.total_usd,
      cost_alert_needed: alertNeeded
    }
  });
}

return out;

const staticData = $getWorkflowStaticData('global');
if (!staticData.monthlyCost) {
  staticData.monthlyCost = {};
}

const inputItems = $input.all();
for (const item of inputItems) {
  const key = item.json.cost_month_key;
  if (key && staticData.monthlyCost[key]) {
    staticData.monthlyCost[key].alert_sent = true;
    staticData.monthlyCost[key].updated_at = new Date().toISOString();
  }
}

return inputItems;

