const store = $getWorkflowStaticData('global');
if (!store.pendingDeleteBySender) store.pendingDeleteBySender = {};

const sender = $json.sender_phone;
const pending = sender ? store.pendingDeleteBySender[sender] : undefined;
const now = Date.now();

if (pending && new Date(pending.expiresAt).getTime() > now) {
  return [{ json: { ...$json, has_pending_delete: true, pending_delete: pending } }];
}

if (pending && sender) delete store.pendingDeleteBySender[sender];
return [{ json: { ...$json, has_pending_delete: false } }];

const text = String($json.incoming_text || '').trim().toLowerCase();
const isConfirm = /^(yes|y|confirm|delete it|yes, delete it|go ahead|do it)$/i.test(text);

return [{
  json: {
    ...$json,
    is_confirm_delete: isConfirm
  }
}];

const store = $getWorkflowStaticData('global');
if (!store.pendingDeleteBySender) store.pendingDeleteBySender = {};

if ($json.sender_phone) delete store.pendingDeleteBySender[$json.sender_phone];
return [{ json: $json }];

return [{
  json: {
    ...$json,
    output: `Done. I deleted "${$json.pending_delete?.title || 'the event'}" scheduled at ${$json.pending_delete?.start || 'the selected time'}.`
  }
}];

const store = $getWorkflowStaticData('global');
if (!store.pendingDeleteBySender) store.pendingDeleteBySender = {};

const text = String($json.output || '');
const tokenRegex = /\[\[PENDING_DELETE\|eventId=([^|\]]+)\|title=([^|\]]*)\|start=([^\]]+)\]\]/;
const match = text.match(tokenRegex);

if (match && $json.sender_phone) {
  const [, eventId, title, start] = match;
  store.pendingDeleteBySender[$json.sender_phone] = {
    action: 'delete',
    eventId: eventId.trim(),
    title: title.trim(),
    start: start.trim(),
    expiresAt: new Date(Date.now() + (10 * 60 * 1000)).toISOString()
  };
}

const cleanedOutput = text.replace(tokenRegex, '').trim();
return [{ json: { ...$json, output: cleanedOutput || text } }];

const msg = $json.body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0] || {};
const sender = msg.from || $json.sender_phone;
const audioId = msg.audio?.id;

if (!audioId) {
  return [{
    json: {
      ...$json,
      sender_phone: sender,
      incoming_text: ''
    }
  }];
}

const waToken = process.env.WHATSAPP_TOKEN || process.env.WHATSAPP_ACCESS_TOKEN || process.env.META_WHATSAPP_TOKEN;
const openAiKey = process.env.OPENAI_API_KEY;

if (!waToken) {
  throw new Error('Missing WhatsApp token env var. Set one of: WHATSAPP_TOKEN, WHATSAPP_ACCESS_TOKEN, META_WHATSAPP_TOKEN');
}
if (!openAiKey) {
  throw new Error('Missing OPENAI_API_KEY env var for audio transcription');
}

const mediaInfoRes = await fetch('https://graph.facebook.com/v25.0/' + audioId, {
  headers: { Authorization: 'Bearer ' + waToken }
});
if (!mediaInfoRes.ok) {
  const txt = await mediaInfoRes.text();
  throw new Error('Failed to fetch media info: ' + mediaInfoRes.status + ' ' + txt);
}
const mediaInfo = await mediaInfoRes.json();

const mediaRes = await fetch(mediaInfo.url, {
  headers: { Authorization: 'Bearer ' + waToken }
});
if (!mediaRes.ok) {
  const txt = await mediaRes.text();
  throw new Error('Failed to download media: ' + mediaRes.status + ' ' + txt);
}

const ab = await mediaRes.arrayBuffer();
const contentType = mediaRes.headers.get('content-type') || 'audio/ogg';
const blob = new Blob([ab], { type: contentType });

const form = new FormData();
form.append('model', 'gpt-4o-mini-transcribe');
form.append('file', blob, 'voice.ogg');

const sttRes = await fetch('https://api.openai.com/v1/audio/transcriptions', {
  method: 'POST',
  headers: { Authorization: 'Bearer ' + openAiKey },
  body: form
});

if (!sttRes.ok) {
  const txt = await sttRes.text();
  throw new Error('Transcription failed: ' + sttRes.status + ' ' + txt);
}

const stt = await sttRes.json();
const transcript = String(stt.text || '').trim();

return [{
  json: {
    ...$json,
    sender_phone: sender,
    incoming_text: transcript,
    audio_transcribed: true
  }
}];
